import React, { useState, useEffect } from 'react';
import { db } from '../data/db';
import { useLiveQuery } from "dexie-react-hooks";

export const FormularioPreventa = () => {
  const [formData, setFormData] = useState({ cliente: '', producto: '', cantidad: 1 });
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [sincronizando, setSincronizando] = useState(false);
  const [pedidosEnServidor, setPedidosEnServidor] = useState([]);

  // 1. Obtener pedidos guardados localmente en este dispositivo (Laptop o Cel)
  const pedidosLocales = useLiveQuery(() => db.pedidos.toArray());

  // 2. Función para que la Laptop vea lo que el servidor ha recibido del celular
  const consultarServidorCentral = async () => {
    try {
      // Usamos la IP para que la conexión sea directa y no choque
      const res = await fetch('http://192.168.1.221:3001/api/pedidos');
      const data = await res.json();
      setPedidosEnServidor(data);
    } catch (e) {
      console.log("Servidor central no alcanzado");
    }
  };

  // 3. Control de conexión y auto-actualización del panel central
  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    
    // Actualiza la lista del servidor cada 3 segundos automáticamente
    const intervalo = setInterval(consultarServidorCentral, 3000);
    
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
      clearInterval(intervalo);
    };
  }, []);

  // 4. Guardar pedido en la base de datos local (Modo Offline)
  const guardarLocalmente = async (e) => {
    e.preventDefault();
    try {
      await db.pedidos.add({ 
        ...formData, 
        fecha: new Date().toISOString(), 
        sincronizado: 0 
      });
      setFormData({ cliente: '', producto: '', cantidad: 1 });
      alert("✔ Guardado en la memoria del dispositivo");
    } catch (error) {
      console.error("Error al guardar localmente:", error);
    }
  };

  // 5. Enviar pedidos pendientes del Celular hacia la Laptop
  const enviarALaLaptop = async () => {
    if (!isOnline) {
      alert("No hay conexión a internet para sincronizar");
      return;
    }

    setSincronizando(true);
    const pendientes = await db.pedidos.where('sincronizado').equals(0).toArray();

    if (pendientes.length === 0) {
      alert("No hay pedidos pendientes por sincronizar");
      setSincronizando(false);
      return;
    }

    for (const p of pendientes) {
      try {
        const res = await fetch('http://192.168.1.221:3001/api/pedidos', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(p)
        });
        
        if (res.ok) {
          // Marcar como sincronizado en el celular si la lap respondió bien
          await db.pedidos.update(p.id, { sincronizado: 1 });
        }
      } catch (e) {
        console.error("Error enviando pedido:", e);
        break;
      }
    }
    
    setSincronizando(false);
    consultarServidorCentral();
  };

  return (
    <div style={{ padding: '20px', maxWidth: '500px', margin: 'auto', fontFamily: 'Arial, sans-serif' }}>
      {/* Indicador de Estado */}
      <div style={{ 
        background: isOnline ? '#d4edda' : '#f8d7da', 
        color: isOnline ? '#155724' : '#721c24',
        padding: '10px', textAlign: 'center', borderRadius: '8px', fontWeight: 'bold' 
      }}>
        {isOnline ? '🟢 DISPOSITIVO CONECTADO' : '🔴 TRABAJANDO OFFLINE'}
      </div>
      
      {/* Formulario de Registro */}
      <form onSubmit={guardarLocalmente} style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' }}>
        <h2 style={{ textAlign: 'center', margin: '0' }}>Preventa MakingPIT</h2>
        <input style={{ padding: '12px', fontSize: '16px', borderRadius: '5px', border: '1px solid #ccc' }} 
          type="text" placeholder="Nombre del Cliente" value={formData.cliente} 
          onChange={e => setFormData({...formData, cliente: e.target.value})} required />
        
        <input style={{ padding: '12px', fontSize: '16px', borderRadius: '5px', border: '1px solid #ccc' }} 
          type="text" placeholder="Producto / Servicio" value={formData.producto} 
          onChange={e => setFormData({...formData, producto: e.target.value})} required />
          
        <button type="submit" style={{ 
          padding: '15px', background: '#28a745', color: 'white', 
          fontWeight: 'bold', border: 'none', borderRadius: '5px', cursor: 'pointer' 
        }}>
          GUARDAR PEDIDO
        </button>
      </form>

      {/* Botón de Sincronización */}
      <button onClick={enviarALaLaptop} disabled={sincronizando} style={{ 
        marginTop: '15px', width: '100%', padding: '15px', background: '#007bff', 
        color: 'white', fontWeight: 'bold', border: 'none', borderRadius: '5px',
        opacity: sincronizando ? 0.6 : 1
      }}>
        {sincronizando ? 'ENVIANDO DATOS...' : 'SINCRONIZAR CON SERVIDOR CENTRAL'}
      </button>

      {/* Lista Local del Dispositivo */}
      <div style={{ marginTop: '30px' }}>
        <h4 style={{ borderBottom: '2px solid #eee', paddingBottom: '5px' }}>📦 Historial Local:</h4>
        {pedidosLocales?.map(p => (
          <div key={p.id} style={{ 
            fontSize: '14px', padding: '8px', borderBottom: '1px solid #eee', 
            display: 'flex', justifyContent: 'space-between',
            background: p.sincronizado ? '#f8f9fa' : '#fff'
          }}>
            <span>{p.cliente} - {p.producto}</span>
            <span title={p.sincronizado ? "Sincronizado" : "Pendiente"}>
              {p.sincronizado ? '✅' : '⏳'}
            </span>
          </div>
        ))}
      </div>

      {/* PANEL CENTRAL: Esto muestra lo que ha llegado al servidor global */}
      <div style={{ marginTop: '30px', background: '#343a40', color: 'white', padding: '15px', borderRadius: '10px' }}>
        <h4 style={{ margin: '0 0 10px 0', color: '#ffc107' }}>🖥️ Servidor Central (Laptop)</h4>
        {pedidosEnServidor.length === 0 ? 
          <p style={{ fontSize: '12px', color: '#adb5bd' }}>Esperando sincronización de dispositivos...</p> : 
          pedidosEnServidor.map((p, i) => (
            <div key={i} style={{ 
              background: '#495057', margin: '8px 0', padding: '10px', 
              borderRadius: '5px', borderLeft: '4px solid #ffc107' 
            }}>
              <div style={{ fontSize: '14px', fontWeight: 'bold' }}>{p.cliente}</div>
              <div style={{ fontSize: '12px' }}>Pedido: {p.producto}</div>
            </div>
          ))
        }
      </div>
    </div>
  );
};
